// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {ERC721} from "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Strings} from "@openzeppelin/contracts/utils/Strings.sol";
import {Base64} from "@openzeppelin/contracts/utils/Base64.sol";
import {BitMaps} from "@openzeppelin/contracts/utils/structs/BitMaps.sol";
import {SSTORE2} from "solady/utils/SSTORE2.sol";

/// @title danta V2 — 10,000 egg tarts on BNB Chain
/// @notice Only 2,000 tokens in total are free (gas only), at most 1 free token per wallet,
///         first come first served. Every other token costs `price` of the payment token
///         (1 USDT by default). Each wallet may mint up to 5.
///         Buyers `approve` this contract for the exact amount shown by `quote` before paid mints.
///         Tokens airdropped by the owner (to holders of the V1 contract) count as free tokens.
contract DantaV2 is ERC721, Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;
    using Strings for uint256;
    using BitMaps for BitMaps.BitMap;

    uint256 public constant MAX_SUPPLY = 10_000;
    uint256 public constant MAX_PER_WALLET = 5;
    uint256 public constant FREE_SUPPLY = 2_000;

    IERC20 public immutable paymentToken; // BSC USDT (18 decimals)
    uint256 public price;                 // per paid token, in paymentToken units

    uint256 public totalSupply;
    uint256 public freeMinted;            // free + airdropped tokens so far (<= FREE_SUPPLY)
    bool public mintOpen;
    string public baseURI;                // optional override (e.g. ipfs://.../)
    address public imagePointer;          // SSTORE2 pointer holding the image URI bytes

    mapping(address => uint256) public mintedBy;
    BitMaps.BitMap private _paid;         // tokenId => minted as a paid token

    event MintOpenSet(bool open);
    event PriceSet(uint256 price);
    event BaseURISet(string uri);
    event ImageSet(address pointer, uint256 length);
    event Withdrawn(address indexed to, uint256 amount);
    event Airdropped(uint256 firstId, uint256 count);

    error MintClosed();
    error ZeroQuantity();
    error WalletLimit();
    error SoldOut();
    error FreeSupplyExceeded();
    error ZeroAddress();

    constructor(address initialOwner, IERC20 paymentToken_, uint256 price_)
        ERC721("danta", "DANTA")
        Ownable(initialOwner)
    {
        paymentToken = paymentToken_;
        price = price_;
    }

    // ---------------------------------------------------------------- mint

    /// @notice How many free tokens `minter` would get right now (0 or 1).
    function freeAvailable(address minter) public view returns (uint256) {
        return (mintedBy[minter] == 0 && freeMinted < FREE_SUPPLY) ? 1 : 0;
    }

    /// @notice Cost for `minter` to mint `quantity` now.
    function quote(address minter, uint256 quantity) public view returns (uint256) {
        if (quantity == 0) return 0;
        return (quantity - freeAvailable(minter)) * price;
    }

    function mint(uint256 quantity) external nonReentrant {
        if (!mintOpen) revert MintClosed();
        if (quantity == 0) revert ZeroQuantity();
        if (mintedBy[msg.sender] + quantity > MAX_PER_WALLET) revert WalletLimit();
        if (totalSupply + quantity > MAX_SUPPLY) revert SoldOut();

        uint256 free = freeAvailable(msg.sender);
        uint256 cost = (quantity - free) * price;
        uint256 firstId = totalSupply + 1;
        mintedBy[msg.sender] += quantity;
        totalSupply += quantity;
        freeMinted += free;
        // the free token (if any) takes the first id; the rest are paid
        for (uint256 i = free; i < quantity; ++i) {
            _paid.set(firstId + i);
        }

        if (cost > 0) paymentToken.safeTransferFrom(msg.sender, address(this), cost);
        for (uint256 i; i < quantity; ++i) {
            _safeMint(msg.sender, firstId + i);
        }
    }

    /// @notice Owner mints one free-tier token to each address in `to` (duplicates allowed,
    ///         one token per entry). Used to re-issue the V1 holders' tokens. No payment.
    ///         Counts toward FREE_SUPPLY, MAX_SUPPLY and the recipient's MAX_PER_WALLET.
    function airdrop(address[] calldata to) external onlyOwner nonReentrant {
        uint256 n = to.length;
        if (n == 0) revert ZeroQuantity();
        if (totalSupply + n > MAX_SUPPLY) revert SoldOut();
        if (freeMinted + n > FREE_SUPPLY) revert FreeSupplyExceeded();

        uint256 firstId = totalSupply + 1;
        totalSupply += n;
        freeMinted += n;
        for (uint256 i; i < n; ++i) {
            address r = to[i];
            if (r == address(0)) revert ZeroAddress();
            if (++mintedBy[r] > MAX_PER_WALLET) revert WalletLimit();
            _mint(r, firstId + i);
        }
        emit Airdropped(firstId, n);
    }

    // ---------------------------------------------------------------- metadata

    /// @notice True if `tokenId` was minted as a paid token.
    function isPaid(uint256 tokenId) public view returns (bool) {
        _requireOwned(tokenId);
        return _paid.get(tokenId);
    }

    function tokenURI(uint256 tokenId) public view override returns (string memory) {
        _requireOwned(tokenId);
        if (bytes(baseURI).length != 0) {
            return string.concat(baseURI, tokenId.toString());
        }
        bool paid = _paid.get(tokenId);
        string memory image = imagePointer == address(0) ? "" : string(SSTORE2.read(imagePointer));
        bytes memory json = abi.encodePacked(
            '{"name":"danta #', tokenId.toString(),
            '","description":"danta - a freshly baked egg tart on BNB Chain.","image":"', image,
            '","background_color":"', paid ? "F5C542" : "FFFFFF",
            '","attributes":[{"trait_type":"Tier","value":"', paid ? "Paid" : "Free", '"}]}'
        );
        return string.concat("data:application/json;base64,", Base64.encode(json));
    }

    // ---------------------------------------------------------------- owner

    function setMintOpen(bool open) external onlyOwner {
        mintOpen = open;
        emit MintOpenSet(open);
    }

    function setPrice(uint256 price_) external onlyOwner {
        price = price_;
        emit PriceSet(price_);
    }

    function setBaseURI(string calldata uri) external onlyOwner {
        baseURI = uri;
        emit BaseURISet(uri);
    }

    /// @notice Store the shared image URI on-chain (e.g. "data:image/webp;base64,..." or "ipfs://...").
    function setImage(bytes calldata imageURI) external onlyOwner {
        address pointer = SSTORE2.write(imageURI);
        imagePointer = pointer;
        emit ImageSet(pointer, imageURI.length);
    }

    /// @notice Withdraw all collected payment tokens to the owner.
    function withdraw() external onlyOwner {
        uint256 bal = paymentToken.balanceOf(address(this));
        paymentToken.safeTransfer(owner(), bal);
        emit Withdrawn(owner(), bal);
    }

    /// @notice Rescue any other ERC-20 accidentally sent here.
    function withdrawToken(IERC20 token) external onlyOwner {
        token.safeTransfer(owner(), token.balanceOf(address(this)));
    }
}
